// Package app file materials for other AIs into the website (D-593): writing instructions, action
// catalog (D-598), structural schema (D-603), JSON Schema, examples (docs/agent/, generated by
// packages/planner snapshot tests), along with the script for the app file check page (same checks
// as app import, running in the browser) and the CLI self-check script tinkrum-check.js for AIs
// (D-594). Usage: node scripts/build-agent-kit.mjs ../tinkrum-site
import { copyFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { build } from 'esbuild';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const site = process.argv[2];
if (!site || !existsSync(join(site, 'index.html'))) {
  console.error('usage: node scripts/build-agent-kit.mjs <tinkrum-site folder>');
  process.exit(1);
}
const out = join(site, 'assets', 'agent');
mkdirSync(out, { recursive: true });
for (const file of [
  'tinkrum-app-guide.md',
  'tinkrum-app-actions.md',
  'tinkrum-app-patterns.md',
  'tinkrum-app-rules.md',
  'tinkrum-app.schema.json',
  'example-plants.json',
])
  copyFileSync(join(root, 'docs', 'agent', file), join(out, file));
await build({
  entryPoints: [join(root, 'scripts', 'agent-kit', 'checker-entry.ts')],
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: 'es2020',
  minify: true,
  legalComments: 'none',
  outfile: join(out, 'checker.js'),
  logLevel: 'warning',
});
// The same check suite for other AIs to run in their own code environment (D-594): a single file with no external dependencies.
await build({
  entryPoints: [join(root, 'scripts', 'agent-kit', 'check-cli.ts')],
  bundle: true,
  format: 'cjs',
  platform: 'node',
  target: 'node18',
  minify: true,
  legalComments: 'none',
  banner: {
    js: '#!/usr/bin/env node\n// Tinkrum app-file checker: node tinkrum-check.js app.json',
  },
  outfile: join(out, 'tinkrum-check.js'),
  logLevel: 'warning',
});
console.log(`agent kit written to ${out}`);
